async fn qualify_region_transfer(state:&video_kadr_backend::state::AppState,source_project:&video_kadr_backend::db::CompositionProject,source_revision:u64,enabled:&video_kadr_backend::db::CompositionProject,erased:&video_kadr_backend::db::CompositionProject,space_id:&str,original:&[u8],end:u64,expected:&[u8],token:&str){
 let model_free_state=(*state).clone().with_sam_config(None).with_person_config(None);let cancel=tokio_util::sync::CancellationToken::new();
 let command=|path:&str,body:Value|Request::builder().method("POST").uri(path).header("content-type","application/json").header("authorization",format!("Bearer {token}")).body(Body::from(body.to_string())).unwrap();
  use video_kadr_backend::handlers::concat_video_cache::{self as registry,ProjectSource,RegionTransfer};
  let pool=sqlx::sqlite::SqlitePoolOptions::new().max_connections(1).connect_with(sqlx::sqlite::SqliteConnectOptions::new().filename(state.storage.join("app.db")).foreign_keys(true)).await.unwrap();
  let source_binding:video_kadr_backend::domain::concat_video_binding::Binding=serde_json::from_value(content(&erased.document,true)["tracks"][0]["clips"][0]["concatCutout"].clone()).unwrap();
  let mut target_doc=enabled.document.clone();target_doc["compositions"]["root"]["content"]["tracks"][0]["clips"][0]["sourceId"]=json!("alias");target_doc["compositions"]["root"]["content"]["canvas"]=json!({"width":32,"height":16,"fpsMilli":10000,"background":{"red":0,"green":0,"blue":0,"alpha":0}});
  let target=state.db.create_space_composition_project("Transferred regions",&target_doc,&["raw".into()],"smart-owner",space_id).await.unwrap();
  let from=ProjectSource{project:&source_project.id,source_id:"slot",revision:source_revision};let to=ProjectSource{project:&target.id,source_id:"alias",revision:target.revision};
  let transfers:Vec<_>=source_binding.region_tracks.iter().map(|track|RegionTransfer{snapshot:track.snapshot.clone(),target_mask_source_id:"imported-region".into()}).collect();
  let stage_root=state.storage.join("concat-video-region-stages");let stages:std::collections::BTreeSet<_>=std::fs::read_dir(&stage_root).unwrap().map(|e|e.unwrap().path()).collect();
  let count=state.library.list().await.len();let cache_root=state.storage.join("concat-video-caches");let generations=std::fs::read_dir(&cache_root).unwrap().count();
  sqlx::query("CREATE TRIGGER reject_region_transfer BEFORE INSERT ON concat_video_project_region_refs BEGIN SELECT RAISE(ABORT,'controlled region reservation rejection'); END").execute(&pool).await.unwrap();
  assert!(registry::transfer_with_regions(&model_free_state,"smart-owner",from,to,&source_binding.runtime_hash,&source_binding.model_hash,&transfers,&cancel).await.is_err());
  let caches:i64=sqlx::query_scalar("SELECT COUNT(*) FROM concat_video_project_caches WHERE project_id=?").bind(&target.id).fetch_one(&pool).await.unwrap();assert_eq!(caches,0);assert!(std::fs::read_dir(&stage_root).unwrap().all(|e|stages.contains(&e.unwrap().path())));assert!(registry::choice(&model_free_state,"smart-owner",&target.id,"alias",target.revision,&cancel).await.unwrap().is_none());sqlx::query("DROP TRIGGER reject_region_transfer").execute(&pool).await.unwrap();
  for mode in 0..4{let mut wrong=RegionTransfer{snapshot:transfers[0].snapshot.clone(),target_mask_source_id:"imported-region".into()};match mode{0=>wrong.snapshot.source_id="other".into(),1=>wrong.snapshot.source_hash="f".repeat(64),2=>wrong.snapshot.mask_file_hash="f".repeat(64),_=>wrong.target_mask_source_id="slot".into()};assert!(registry::transfer_with_regions(&model_free_state,"smart-owner",from,to,&source_binding.runtime_hash,&source_binding.model_hash,&[wrong],&cancel).await.is_err());}
  let moved=registry::transfer_with_regions(&model_free_state,"smart-owner",from,to,&source_binding.runtime_hash,&source_binding.model_hash,&transfers,&cancel).await.unwrap();let repeated=registry::transfer_with_regions(&model_free_state,"smart-owner",from,to,&source_binding.runtime_hash,&source_binding.model_hash,&transfers,&cancel).await.unwrap();assert_eq!(moved.cache_id,repeated.cache_id);assert_eq!(moved.regions,repeated.regions);assert_eq!(moved.regions.len(),2);assert!(moved.regions.iter().all(|snapshot|snapshot.source_id=="alias"&&snapshot.mask_source_id=="imported-region"));
  let refs:i64=sqlx::query_scalar("SELECT COUNT(*) FROM concat_video_project_region_refs WHERE project_id=?").bind(&target.id).fetch_one(&pool).await.unwrap();assert_eq!(refs,1);assert!(std::fs::read_dir(&stage_root).unwrap().all(|e|stages.contains(&e.unwrap().path())));assert_eq!(state.library.list().await.len(),count);assert_eq!(std::fs::read_dir(&cache_root).unwrap().count(),generations);
  let lease=video_kadr_backend::handlers::concat_video_region_cache::load(&model_free_state,"smart-owner",&target.id,target.revision,&moved.regions[0],&cancel).await.unwrap();drop(lease);
  let physical_mask=&transfers[0].snapshot.mask_source_id;let mut region_source=content(&erased.document,true)["sources"][physical_mask].clone();region_source["id"]=json!("imported-region");
  let mut bound_doc=target_doc.clone();let mut binding=source_binding.clone();for(track,snapshot)in binding.region_tracks.iter_mut().zip(&moved.regions){track.snapshot=snapshot.clone();}
  bound_doc["compositions"]["root"]["content"]["tracks"][0]["clips"][0]["concatCutout"]=serde_json::to_value(binding).unwrap();bound_doc["compositions"]["root"]["content"]["sources"]["imported-region"]=region_source.clone();bound_doc["projectMedia"]["imported-region"]=json!({"source":region_source,"librarySourceId":physical_mask,"name":"Imported smart region","placeholder":false});
  let mut sources=vec!["raw".to_owned(),physical_mask.clone()];sources.sort();let attached=state.db.update_composition_project_for(&target.id,"smart-owner",&target.name,&bound_doc,&sources,target.revision).await.unwrap().unwrap();
  let reverted=state.db.update_composition_project_for(&target.id,"smart-owner",&target.name,&target_doc,&["raw".into()],attached.revision).await.unwrap().unwrap();
  // Rebind the inactive live bin slot; the old snapshot must still resolve its
  // exact historical file for a draft Redo, rather than follow the new live file.
  let mut retargeted=target_doc.clone();let mut other_source=retargeted["compositions"]["root"]["content"]["sources"]["alias"].clone();other_source["id"]=json!("imported-region");retargeted["compositions"]["root"]["content"]["sources"]["imported-region"]=other_source.clone();retargeted["projectMedia"]["imported-region"]=json!({"source":other_source,"librarySourceId":"raw","name":"Other live file","placeholder":false});
  let retargeted=state.db.update_composition_project_for(&target.id,"smart-owner",&target.name,&retargeted,&["raw".into()],reverted.revision).await.unwrap().unwrap();
  let requested:video_kadr_backend::domain::nested_composition::NestedCompositionProject=serde_json::from_value(bound_doc.clone()).unwrap();let context=video_kadr_backend::handlers::concat_video_bound::SavedProject{project_id:target.id.clone(),expected_revision:retargeted.revision};
  let mut provider=video_kadr_backend::handlers::concat_video_bound::BoundMasks::load(&model_free_state,"smart-owner",Some(&context),&requested,&cancel).await.unwrap();let mut frame=video_kadr_backend::domain::group_surface::GroupSurface{width:32,height:16,rgba:original[2*32*16*4..3*32*16*4].to_vec()};provider.apply("root",&video_kadr_backend::domain::composition::CompositionClipId::parse("clip").unwrap(),&video_kadr_backend::domain::composition::SourceId::parse("alias").unwrap(),end-1,&mut frame).unwrap();assert_eq!(frame.rgba,expected);
  let mut forged=bound_doc.clone();forged["projectMedia"]["imported-region"]["librarySourceId"]=json!("raw");let forged=serde_json::from_value(forged).unwrap();assert!(video_kadr_backend::handlers::concat_video_bound::BoundMasks::load(&model_free_state,"smart-owner",Some(&context),&forged,&cancel).await.is_err());
  for strokes in [1,2]{
   let mut source_view=erased.document.clone();source_view["compositions"]["root"]["content"]["canvas"]=target_doc["compositions"]["root"]["content"]["canvas"].clone();
   let mut target_view=bound_doc.clone();for doc in [&mut source_view,&mut target_view]{let binding=&mut doc["compositions"]["root"]["content"]["tracks"][0]["clips"][0]["concatCutout"];binding["correction"]["strokes"].as_array_mut().unwrap().truncate(strokes);binding["regionTracks"].as_array_mut().unwrap().truncate(strokes);}
   let app=support::router(model_free_state.clone());let render=|project:Value,context:Value|command("/api/compositions/nested-preview",json!({"project":project,"compositionId":"root","timeUs":249999,"renderedOutputs":{},"savedProject":context}));
   let response=app.clone().oneshot(render(source_view,json!({"projectId":source_project.id,"expectedRevision":source_revision}))).await.unwrap();let status=response.status();let reference=to_bytes(response.into_body(),1024*1024).await.unwrap();assert_eq!(status,StatusCode::OK,"{}",String::from_utf8_lossy(&reference));if strokes==1{assert!(reference.chunks_exact(4).any(|p|p[3]>0),"brush fixture must have visible pixels");}
   let mut imported=target_view.clone();
   imported["compositions"]["root"]["content"]["tracks"][0]["clips"][0]["concatCutout"]["origin"]=json!({"projectId":source_project.id,"expectedRevision":source_revision,"sourceId":"slot","regionSources":{"imported-region":physical_mask}});
   let response=app.clone().oneshot(render(imported.clone(),Value::Null)).await.unwrap();let status=response.status();let draft=to_bytes(response.into_body(),1024*1024).await.unwrap();assert_eq!(status,StatusCode::OK,"{}",String::from_utf8_lossy(&draft));assert!(draft==reference,"unsaved origin preview differs with {strokes} strokes");
   if strokes==2 {Box::pin(qualify_atomic_region_save(&model_free_state,space_id,&source_project.id,token,&imported,&reference)).await;}
   let response=app.oneshot(render(target_view,serde_json::to_value(&context).unwrap())).await.unwrap();let status=response.status();let actual=to_bytes(response.into_body(),1024*1024).await.unwrap();assert_eq!(status,StatusCode::OK,"{}",String::from_utf8_lossy(&actual));assert!(actual==reference,"transferred native preview differs with {strokes} strokes");
  }
  let third=state.db.create_space_composition_project("Transferred again",&enabled.document,&["raw".into()],"smart-owner",space_id).await.unwrap();let chained:Vec<_>=moved.regions.iter().map(|snapshot|RegionTransfer{snapshot:snapshot.clone(),target_mask_source_id:"third-region".into()}).collect();
  let third_store=registry::transfer_with_regions(&model_free_state,"smart-owner",ProjectSource{project:&target.id,source_id:"alias",revision:retargeted.revision},ProjectSource{project:&third.id,source_id:"slot",revision:third.revision},&source_binding.runtime_hash,&source_binding.model_hash,&chained,&cancel).await.unwrap();
  sqlx::query("DELETE FROM composition_projects WHERE id=?").bind(&target.id).execute(&pool).await.unwrap();assert!(video_kadr_backend::handlers::concat_video_region_cache::load(&model_free_state,"smart-owner",&third.id,third.revision,&third_store.regions[0],&cancel).await.is_ok());

}

async fn qualify_atomic_region_save(state:&video_kadr_backend::state::AppState,space:&str,source_project:&str,token:&str,imported:&Value,expected:&[u8]){
 let pool=sqlx::sqlite::SqlitePoolOptions::new().max_connections(1).connect_with(sqlx::sqlite::SqliteConnectOptions::new().filename(state.storage.join("app.db")).foreign_keys(true)).await.unwrap();let app=support::router(state.clone());
 let command=|path:&str,body:Value|Request::builder().method("POST").uri(path).header("content-type","application/json").header("authorization",format!("Bearer {token}")).body(Body::from(body.to_string())).unwrap();
 let count:i64=sqlx::query_scalar("SELECT COUNT(*) FROM composition_projects").fetch_one(&pool).await.unwrap();
 let body=json!({"schemaVersion":2,"mode":"composition","name":"Atomic region adoption","spaceId":space,"document":imported});
 sqlx::query("CREATE TRIGGER reject_atomic_region BEFORE INSERT ON concat_video_project_region_refs BEGIN SELECT RAISE(ABORT,'controlled region save rejection'); END").execute(&pool).await.unwrap();
 assert!(!app.clone().oneshot(command("/api/composition-projects",body.clone())).await.unwrap().status().is_success());
 let after:i64=sqlx::query_scalar("SELECT COUNT(*) FROM composition_projects").fetch_one(&pool).await.unwrap();assert_eq!(after,count);
 sqlx::query("DROP TRIGGER reject_atomic_region").execute(&pool).await.unwrap();
 let response=app.clone().oneshot(command("/api/composition-projects",body)).await.unwrap();let status=response.status();let bytes=to_bytes(response.into_body(),1024*1024).await.unwrap();assert!(status.is_success(),"{}",String::from_utf8_lossy(&bytes));let saved:Value=serde_json::from_slice(&bytes).unwrap();let id=saved["id"].as_str().unwrap();
 let owned=state.db.get_composition_project_for(id,"smart-owner").await.unwrap().unwrap();assert!(owned.document["compositions"]["root"]["content"]["tracks"][0]["clips"][0]["concatCutout"].get("origin").is_none());
 let refs:i64=sqlx::query_scalar("SELECT COUNT(*) FROM concat_video_project_region_refs WHERE project_id=?").bind(id).fetch_one(&pool).await.unwrap();assert_eq!(refs,1);
 sqlx::query("UPDATE composition_project_members SET role='viewer' WHERE project_id=? AND actor='smart-owner'").bind(source_project).execute(&pool).await.unwrap();
 let draft:video_kadr_backend::domain::nested_composition::NestedCompositionProject=serde_json::from_value(imported.clone()).unwrap();assert!(video_kadr_backend::handlers::concat_video_bound::BoundMasks::load(state,"smart-owner",None,&draft,&tokio_util::sync::CancellationToken::new()).await.is_err());
 let response=app.oneshot(command("/api/compositions/nested-preview",json!({"project":owned.document,"compositionId":"root","timeUs":249999,"renderedOutputs":{},"savedProject":{"projectId":id,"expectedRevision":owned.revision}}))).await.unwrap();let status=response.status();let pixels=to_bytes(response.into_body(),1024*1024).await.unwrap();assert_eq!(status,StatusCode::OK,"{}",String::from_utf8_lossy(&pixels));assert_eq!(pixels.as_ref(),expected);
 sqlx::query("UPDATE composition_project_members SET role='owner' WHERE project_id=? AND actor='smart-owner'").bind(source_project).execute(&pool).await.unwrap();
}
